class Ingestor:
    """Reads batches off an at-least-once queue and writes the ones we care about to the warehouse."""

    ALLOWED = {"click", "purchase"}

    def __init__(self, sink):
        self.sink = sink

    def ingest(self, batch):
        rows = [event for event in batch if event.kind in self.ALLOWED]
        self.sink.write(rows)
        return len(rows)

